import numpy as np, random, time, copy
from scipy import sparse
from reference import Task

def solver_params(maxiter_factor=40, tol=1e-6, ncv=None):
    def solve(problem):
        A=problem['matrix'];k=problem['k'];N=A.shape[0]
        v0=np.ones(N, dtype=A.dtype)
        ncv_val=ncv if ncv is not None else max(2*k+1,20)
        vals, vecs = sparse.linalg.eigs(A,k=k,v0=v0,ncv=ncv_val,maxiter=N*maxiter_factor,tol=tol)
        pairs=sorted(zip(vals, vecs.T), key=lambda p:-abs(p[0]))
        return [p[1] for p in pairs]
    return solve

def test_solver(solve, ncases=200):
    random.seed(0)
    ok=0; fail=0
    total_time=0
    for i in range(ncases):
        prob=Task().generate_problem(n=300, random_seed=random.randrange(10**9))
        start=time.perf_counter();
        try:
            sol=solve(copy.deepcopy(prob))
        except Exception:
            fail+=1; continue
        total_time+=time.perf_counter()-start
        if Task().is_solution(prob, sol):
            ok+=1
        else:
            fail+=1
    return ok, fail, total_time

for fac in [20,30,40,60,80,100]:
    for tol in [1e-6,1e-7,1e-8]:
        solver=solver_params(maxiter_factor=fac,tol=tol,ncv=20)
        ok, fail, ttime=test_solver(solver, ncases=50)
        print('fac',fac,'tol',tol,'ok',ok,'fail',fail,'avg_time', ttime/(ok+fail))
