import time, random, copy, numpy as np
from scipy import sparse
from reference import Task


def fast_attempt(problem):
    A=problem['matrix']; k=problem['k']; N=A.shape[0]
    v0=np.ones(N,dtype=A.dtype)
    ncv=max(2*k+1,40)  # 40 > 20 for better convergence
    try:
        vals, vecs = sparse.linalg.eigs(A,k=k,v0=v0,ncv=ncv,maxiter=N*60,tol=1e-8)
    except Exception as e:
        return None
    pairs=sorted(zip(vals, vecs.T), key=lambda p:-abs(p[0]))
    return [p[1] for p in pairs]

def solver(problem):
    sol=fast_attempt(problem)
    if sol is None or not Task().is_solution(problem, sol):
        sol = Task().solve(problem)
    return sol

random.seed(0)
problems=[Task().generate_problem(n=300, random_seed=random.randrange(10**9)) for _ in range(30)]
start=time.perf_counter();
for p in problems:
    Task().solve(copy.deepcopy(p))
ref_t=time.perf_counter()-start
start=time.perf_counter();
for p in problems:
    solver(copy.deepcopy(p))
sol_t=time.perf_counter()-start
print('ref',ref_t,'sol',sol_t,'speedup',ref_t/sol_t)
